namespace LaTerzaCampana.Core;
public static class AnatemaOrigin103 {
 public sealed record Beat(string Speaker,string Text);
 public sealed record Option(string Label,string Result,int Mind=0,int Body=0,string Item="",string Gear="",string Trait="");
 public sealed record Scene(string Title,string Era,Beat[] Beats,Option[] Options,string Bridge);
 public static readonly Scene[] Scenes=[
 new("Il figlio sbagliato","INFANZIA",[new("NARRATORE","In una casa dove perfino il pane era un lusso, un bambino nacque con marchi sulla pelle e capelli dalle spirali innaturali. Sua madre non riusciva a guardarlo."),new("EMILÈ","Mamma, posso sedermi vicino a te? Ho freddo."),new("MADRE","Copriti il viso! Quante volte devo dirtelo? Non voglio guardarlo mentre mangio."),new("EMILÈ","Se mi lavo ancora, forse i segni vanno via."),new("PADRE","Basta. Il ragazzo deve mangiare. Domani viene con me a lavorare."),new("NARRATORE","La notte, Emilè provò a chiedere agli dei ciò che in casa non trovava. Si risvegliò con altri segni sulla pelle: non aveva ottenuto conforto, ma era stato consacrato a sua insaputa.")],[new("Chiedi agli dèi il suo amore","Ti accosti a tua madre dopo una preghiera. Lei si volta dall'altra parte.",-5),new("Offri agli dèi la tua fatica","Aiuti tuo padre e offri agli dèi il peso degli attrezzi, sperando di essere ascoltato.",0,-4,Trait:"forgia"),new("Chiedi che i marchi svaniscano","Ti copri con un cappuccio trovato tra gli stracci e aspetti un miracolo.",Gear:"cappuccio"),new("Prega fino all'alba","Le voci ridono. Continui a pregare, senza ricevere una risposta.",-8)],"Passarono alcuni inverni. Una voce nuova sembrò finalmente ascoltarlo."),
 new("Una madre celeste","QUALCHE ANNO DOPO",[new("NUWDANÌE","Povero piccolo. Nessun figlio dovrebbe conoscere tanta solitudine."),new("EMILÈ","Tu potresti essere la mia mamma?"),new("NUWDANÌE","Posso donare alla tua casa l'amore che le manca."),new("NARRATORE","La dea spinse sua madre tra le braccia di un altro uomo. Nacquero altri bambini. La donna riservò loro tutte le carezze che Emilè aveva chiesto."),new("MADRE","Non svegliarli. Vai via, Emilè."),new("NUWDANÌE","Vedi? Tua madre era perfettamente capace di amare."),new("EMILÈ","Allora perché non me?")],[new("Segui il consiglio di Nuwdanìe","Porgi una coperta a tua madre, sperando che la dea la intenerisca. Lei non la prende."),new("Cerca un altro segno divino","Esci per pregare in solitudine. Forse un altro dio saprà comprenderti.",Trait:"indesiderato"),new("Implora Nuwdanìe di aiutarti","Le chiedi perché non ha riservato un po' d'amore anche a te. Una risata è la sola risposta.",-6)],"Crescendo, Emilè iniziò a desiderare un mondo in cui non fosse un errore."),
 new("Il mondo migliore","ADOLESCENZA",[new("EMILÈ","Nyarlatoth, ti prego. Non voglio più vivere in questo mondo."),new("NYARLATOTH","Allora permettimi di mostrartene un altro."),new("NARRATORE","Gli specchi iniziarono a mostrare stanze che non esistevano. Le porte si ripetevano, e le voci avevano il suono di persone ormai lontane. Il dono alterò la sua percezione."),new("EMILÈ","Non è questo che ti avevo chiesto."),new("NYARLATOTH","Un mondo diverso, hai detto. Non un mondo felice.")],[new("Affidati al mondo promesso","Segui il riflesso di Nyarlatoth. Il corridoio non finisce mai; la realtà si confonde.",-10),new("Chiedi al dio cosa sia reale","Cerchi un segno che distingua ricordi e miraggi. Impari a riconoscerli, ma non trovi pace.",Trait:"lucidita"),new("Chiedi di rivedere tuo padre","Implori Nyarlatoth di restituirti almeno quella voce. Il ricordo ti riporta al presente.",4),new("Supplica Nyarlatoth di fermarsi","Le porte continuano a moltiplicarsi. Gli chiedi ancora di ricondurti a casa.",-3)],"Fra tutte le illusioni, una persona restava riconoscibile."),
 new("L'ultimo uomo della casa","ADOLESCENZA",[new("PADRE","Smettila di coprirti la faccia quando sei con me."),new("EMILÈ","Alla mamma non piace."),new("PADRE","Non ho detto che deve piacerle."),new("NARRATORE","Suo padre era un uomo all'antica, duro e poco incline alle parole tenere. Quel giorno divise con lui l'ultima razione di pane."),new("PADRE","Mangia. Domani abbiamo da lavorare.")],[new("Prega per il lavoro di tuo padre","Impari il mestiere e tuo padre ti lascia il vecchio martello. Chiedi agli dèi di custodirlo.",Gear:"martello"),new("Custodisci il suo medaglione","Conservi il medaglione e chiedi agli dèi di proteggere l'unico uomo che ti vuole bene.",Gear:"medaglione"),new("Prega perché resti con te","Resti seduto accanto a lui. Per una volta il silenzio non è una punizione; chiedi che duri.",5),new("Conserva il pane per domani","Metti da parte la razione per il viaggio e preghi perché a tuo padre non manchi più nulla.",Item:"pane")],"Fu allora che Emilè decise di invocare l'ultimo dei tre dei."),
 new("Il funerale di mio padre","DOPO LA DEVASTAZIONE",[new("NARRATORE","Emilè aveva chiesto a Braka di vendicarlo degli altri dei. Braka gli aveva promesso aiuto. Tre giorni dopo, nella cappella del paese, una bara portava il nome di suo padre."),new("MADRE","Andiamo, bambini. Non restate qui al freddo."),new("NARRATORE","La madre, il viso nascosto dal velo nero, strinse a sé i due figli più piccoli. Emilè rimase solo davanti alla bara."),new("EMILÈ","Papà… avevi detto che domani saremmo tornati a lavorare."),new("BRAKA","Mi hai offerto ciò che aveva valore. Hai invocato la devastazione, non la giustizia."),new("EMILÈ","Non lui. Non ti avevo chiesto lui. Ti prego…"),new("NARRATORE","Le campane tacquero. Emilè non riusciva a staccare gli occhi dalla bara.")],[new("Implora Braka di restituirtelo","Sfiori il legno freddo e supplichi Braka di rimediare. Non arriva alcuna risposta.",-7),new("Invoca gli altri due dèi","Chiedi a Nuwdanìe e Nyarlatoth ciò che Braka ti ha strappato. Nessuno risponde.",Trait:"rinnegato"),new("Conserva il lino e prega","Ripieghi il lino dei fiori e chiedi che almeno l'anima di tuo padre trovi pace.",-3,Item:"bende")],"Anni dopo, il ricordo del padre lo condusse verso un luogo che non aveva mai visto da sveglio."),
 new("Ciò che non posso vedere","OLTRE IL RICORDO",[new("NARRATORE","Non era un santuario. Non davvero. Le scale tornavano su se stesse; tre presenze occupavano il luogo dove avrebbe dovuto esserci il cielo. Ogni volta che provava a guardarle, qualcosa cancellava i loro volti."),new("EMILÈ","Vi ho chiamati madre, salvatori, giustizia. Da bambino mi avete marchiato come un'offerta. Eppure non riesco nemmeno a vedervi."),new("???","E quale sarebbe il tuo nome, piccolo sacrilegio?"),new("EMILÈ","Emilè."),new("EMILÈ MARAT","Emilè Marat. Non vi appartengo.")],[new("Lascia spegnere le luci","Le ultime luci si dissolvono. Le presenze non hanno più una forma."),new("Volta le spalle alle presenze","Le voci ti seguono, ma non ti dettano più il cammino."),new("Pronuncia il tuo nome","Emilè Marat. Questa volta è il suo nome a rimanere.",3)],"EMILÈ MARAT — L'ANATEMA. Il convoglio delle 03:17 lo attendeva.")];
 public static bool Apply(GameRules g,int scene,int choice){if(g.State.Hero!=HeroId.Anatema||scene<0||scene>=Scenes.Length||choice<0||choice>=Scenes[scene].Options.Length)return false;var s=g.State;if(!s.StoryFlags.Add($"anatema103_choice_{scene}"))return false;var o=Scenes[scene].Options[choice];s.StoryFlags.Add($"anatema103_{scene}_{choice}");s.Mind=Math.Clamp(s.Mind+o.Mind,0,100);s.Body=Math.Clamp(s.Body+o.Body,1,100);if(o.Item.Length>0)g.AddItem(o.Item);if(o.Gear.Length>0)s.OwnedEquipment.Add(o.Gear);if(o.Trait.Length>0)s.StoryFlags.Add("anatema103_"+o.Trait);return true;}
}
